// Prove that every SHIPPED build subtree on disk is what a clean build produces.
//
// WHY THIS EXISTS. Three subtrees are generated by `npm run build` and two of them
// are copied straight into app.asar by electron-builder.yml (`files:` build/src/**,
// build/gateway/**, build/renderer/**). Nothing verified that the bytes on disk
// came from the CURRENT sources, so a skipped, interrupted or incrementally
// short-circuited build shipped whatever was left behind. Measured before this
// script existed:
//   * build/gateway/server.mjs was 161,217 B while a clean bundle is 163,151 B, and
//     the shipped file did not contain the string "no reasoning output observed"
//     that src/gateway/capability-probe.mjs:693 now emits.
//   * build/renderer carried no `endpoint_creds_error` key, which
//     src/renderer/i18n/resources.ts:142 defines in all 7 locales.
// Both were released. Neither was caught by a test, because every existing check
// only asks whether an artifact EXISTS, never whether it is CURRENT.
//
// HOW IT PROVES IT. For each subtree it re-runs the REAL producer into a throwaway
// directory and compares the two trees file by file on size + SHA-256:
//   build/src       -> `tsc -p tsconfig.node.json` (outDir ./build), with the
//                      tsbuildinfo redirected into the throwaway directory so the
//                      reference emit can never be served from incremental state
//                      (that masking is exactly the defect this must not inherit).
//   build/gateway   -> scripts/build-gateway-bundle.mjs, the same function the npm
//                      script calls, so no esbuild option is duplicated here. The
//                      ROOT is threaded through (see --root): resolving it inside
//                      that module from its own location made every `--root` audit
//                      silently re-bundle THIS repository and compare it against the
//                      audit copy, which reported the copy as stale (or, with the
//                      same tree on both sides, as fresh) no matter what the copy
//                      actually contained.
//   build/renderer  -> `vite build`, the same CLI the npm script calls, with
//                      --outDir redirected. A manifest compare (not just a single
//                      hash) is used because the filenames are content-hashed: a
//                      stale bundle is caught either by a differing hash on a
//                      shared name or by an EXTRA file left from an older emit.
// A file that exists only on disk (extra) is a failure too: electron-builder
// copies the whole directory, so an orphan would ship as well.
//
// TWO MORE CHECKS, because three subtrees were not the whole hole:
//   build/release-notes.md  generated by scripts/release-notes.mjs from CHANGELOG.md
//                           and named by electron-builder.yml releaseInfo.releaseNotesFile,
//                           so it ships into latest.yml and the GitHub release body.
//                           It is in NO other gate. Compared against
//                           extractReleaseNotes() output, byte for byte.
//   --asar                  after packaging: the entries inside
//                           dist/win-unpacked/resources/app.asar (build/gateway/server.mjs,
//                           build/src/main/*.js, build/renderer assets) against build/.
//                           A stale asar is what actually ships, and nothing compared
//                           it: measured on this tree, app.asar was 03:28 while the
//                           sources were 03:51.
//
// COST. Measured on this machine: tsc 4.3 s, vite 5.2 s, esbuild 0.4 s, ~10 s total,
// well under the 60 s budget. --asar reads one archive and costs milliseconds.
//
// USAGE
//   node scripts/verify-build-freshness.mjs                      # all subtrees + notes
//   node scripts/verify-build-freshness.mjs --subtree build/src   # one of them
//   node scripts/verify-build-freshness.mjs --artifact-root DIR    # audit a copy
//   node scripts/verify-build-freshness.mjs --work-dir DIR         # scratch base
//   node scripts/verify-build-freshness.mjs --asar                 # packaged asar vs build/
//   node scripts/verify-build-freshness.mjs --require-release-notes  # absence is a failure
//
// EXIT CODES: 0 fresh, 1 stale artifact(s), 2 the verifier could not produce a
// reference emit or could not read the artifact it was asked to compare (a build
// failure, reported distinctly so a broken toolchain is never mistaken for a stale
// file).

import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_ROOT = path.resolve(SCRIPT_DIR, '..');

/** Where `npm run package:dir` leaves the archive Electron actually loads. */
export const DEFAULT_ASAR_PATH = path.join('dist', 'win-unpacked', 'resources', 'app.asar');

/**
 * The generated directories that ship. `producer` names the real build step so the
 * list cannot drift from the pipeline silently; `verifyBuildFreshness` fails on an
 * id it does not know rather than ignoring it.
 */
export const SHIPPED_SUBTREES = Object.freeze([
  Object.freeze({ id: 'build/src', producer: 'tsc -p tsconfig.node.json (outDir ./build)' }),
  Object.freeze({ id: 'build/gateway', producer: 'scripts/build-gateway-bundle.mjs' }),
  Object.freeze({ id: 'build/renderer', producer: 'vite build (vite.config.ts build.outDir)' })
]);

/**
 * The one generated SHIPPING file outside those subtrees. Same reason as above:
 * a single id so a caller cannot silently drop it.
 */
export const RELEASE_NOTES_ID = 'build/release-notes.md';

/**
 * The asar entries the packaged app cannot work without, plus the directory prefixes
 * whose whole contents are compared. `build/src/main/*.js` and the renderer assets
 * are enumerated from build/ at run time so a newly added module is covered without
 * editing this list; `build/src/preload` needs no enumeration because its prefix
 * below compares the whole directory.
 */
export const ASAR_REQUIRED_FILES = Object.freeze([
  'build/gateway/server.mjs',
  'build/src/preload/index.js',
  'build/renderer/index.html'
]);
export const ASAR_REQUIRED_DIRECTORIES = Object.freeze([
  'build/src/main',
  'build/renderer/assets'
]);
/**
 * `build/src/preload/` is here because electron-builder.yml:9 ships it
 * (`files: build/src/preload/**`) and the prefix list governs the ORPHAN scan — the
 * direction that catches an entry the current build no longer produces. Without it,
 * MEASURED: packing `build/src/preload/stale-orphan.js` into an otherwise current
 * archive still printed ASAR_FRESHNESS_VERIFIED and exited 0, because only the one
 * required `index.js` was read from that directory and nothing enumerated it. A
 * stale preload bridge is the worst place to be blind: it is the only channel
 * between the renderer and the main process.
 */
export const ASAR_COMPARED_PREFIXES = Object.freeze([
  'build/gateway/',
  'build/src/main/',
  'build/src/preload/',
  'build/renderer/'
]);

/**
 * Extensions electron-builder can put in the archive from those prefixes.
 *
 * Derived from the packaging tool, not guessed: app-builder-lib's `excludedExts`
 * (node_modules/app-builder-lib/out/fileMatcher.js:19-21) lists `d.ts`, and
 * electron-builder.yml negates `**\/*.map`. Both are therefore never in a real
 * archive, so an entry with one of those extensions is not a stale leftover and
 * must not be reported as one — that would fail every packaging run on files the
 * packager itself strips.
 */
const ASAR_SHIPPED_EXTENSIONS = Object.freeze(['.js', '.mjs', '.cjs', '.css', '.html', '.json']);

function shipsFromBuild(relative) {
  return ASAR_SHIPPED_EXTENSIONS.some((extension) => relative.endsWith(extension));
}

const SUBTREE_IDS = SHIPPED_SUBTREES.map((subtree) => subtree.id);

function requireFrom(root) {
  return createRequire(path.join(root, 'package.json'));
}

function resolveTypeScriptCli(root) {
  // typescript has no "exports" map, so the deep bin path resolves directly.
  return requireFrom(root).resolve('typescript/bin/tsc');
}

function resolveViteCli(root) {
  // vite DOES have an "exports" map that hides ./bin/vite.js, but it re-exports
  // ./package.json, and package.json#bin names the same entry the npm script runs.
  const packageJsonPath = requireFrom(root).resolve('vite/package.json');
  return path.join(path.dirname(packageJsonPath), 'bin', 'vite.js');
}

/**
 * @electron/asar is not a declared dependency of this project, but it is already
 * load-bearing in the packaging path (scripts/harden-windows-package.mjs imports
 * getRawHeader from it), and it is present as a transitive dependency of
 * electron-builder via @electron/universal. Resolving it from the project root is
 * therefore the same contract the hardening hook already relies on; a failure is a
 * toolchain problem (exit 2), never a stale artifact.
 */
function resolveAsar(root) {
  return requireFrom(root)('@electron/asar');
}

function run(command, args, { cwd, label }) {
  const result = spawnSync(command, args, { cwd, encoding: 'utf8', shell: false });
  if (result.error) {
    throw new Error(`${label} could not start: ${result.error.message}`);
  }
  if (result.status !== 0) {
    const detail = [result.stderr, result.stdout].filter(Boolean).join('\n').trim();
    throw new Error(`${label} failed with exit ${result.status}${detail ? `:\n${detail}` : ''}`);
  }
}

// ── Reference emits ─────────────────────────────────────────────────────────

function emitTypeScript({ root, scratch }) {
  const outDir = path.join(scratch, 'tsc');
  run(process.execPath, [
    resolveTypeScriptCli(root),
    '-p', 'tsconfig.node.json',
    '--outDir', outDir,
    // Redirected on purpose: a reference emit must be a FULL emit, never an
    // incremental no-op. tsc happily exits 0 without rewriting output when a
    // tsbuildinfo says the project is current.
    '--tsBuildInfoFile', path.join(scratch, 'tsconfig.node.tsbuildinfo')
  ], { cwd: root, label: 'reference tsc emit' });
  return assertTypeScriptLayout(outDir);
}

/**
 * Assert the emit landed where the pipeline expects it, or fail as UNVERIFIABLE.
 *
 * WHY: the caller used to return `scratch/tsc/src` and trust it. tsconfig.node.json
 * declares no explicit `rootDir`, so tsc infers the common source directory; adding
 * an `include` outside `src/` (or setting a narrower `rootDir`) moves every output
 * one level and the comparison then reports mass "missing" files — a false POSITIVE
 * that accuses a correct build. The reverse (a `rootDir` that swallows a subtree so
 * it is silently not emitted) is worse: a silent exclusion. Both are layout bugs in
 * the TOOLCHAIN, not stale artifacts, so they exit 2 rather than 1.
 *
 * The anchors: `build/src/main/index.js` is what package.json#main names, so its
 * presence under `src/` proves rootDir is the repository root and the include list
 * still reaches src/main; `src` and `src/main` must be non-empty. `vite.config.js`
 * legitimately sits at the outDir ROOT (it is an include of this project), which is
 * why the check is anchored on src/main rather than on "no files at the root".
 */
export function assertTypeScriptLayout(outDir) {
  const sourceRoot = path.join(outDir, 'src');
  const entry = path.join(sourceRoot, 'main', 'index.js');
  if (!fs.existsSync(entry)) {
    throw new Error(
      `reference tsc emit produced no ${path.join('src', 'main', 'index.js')} under ${outDir}: `
      + 'tsconfig.node.json#rootDir/include moved, so build/src cannot be compared. '
      + 'Fix the tsconfig (rootDir must stay the repository root and src/main must be included).'
    );
  }
  const files = collectFiles(sourceRoot);
  const mainFiles = files.filter((relative) => relative.startsWith('main/'));
  if (files.length === 0 || mainFiles.length === 0) {
    throw new Error(
      `reference tsc emit wrote an empty ${sourceRoot} (files=${files.length}, main=${mainFiles.length}): `
      + 'the include list no longer reaches the sources'
    );
  }
  return sourceRoot;
}

function emitVite({ root, scratch }) {
  const outDir = path.join(scratch, 'vite');
  run(process.execPath, [
    resolveViteCli(root),
    'build',
    '--outDir', outDir,
    '--emptyOutDir',
    '--logLevel', 'warn'
  ], { cwd: root, label: 'reference vite build' });
  return outDir;
}

/**
 * Re-bundle the gateway from `root`, not from this script's own location.
 *
 * `root` is threaded into buildGatewayBundle so the reference emit genuinely comes
 * from the audited tree. Without it, `--root <somewhere>` still bundled THIS
 * repository (measured: a 1-line server.mjs under --root still produced the real
 * 163,151 B bundle), so a `--root` audit compared this repo's bundle against the
 * copy and its verdict said nothing about the copy.
 */
async function emitGateway({ root, scratch }) {
  const module = await import(pathToFileURL(path.join(SCRIPT_DIR, 'build-gateway-bundle.mjs')).href);
  const entryPath = path.join(root, module.GATEWAY_BUNDLE_ENTRY);
  if (!fs.existsSync(entryPath)) {
    throw new Error(
      `reference gateway emit: ${entryPath} does not exist, so ${module.GATEWAY_BUNDLE_ENTRY} `
      + 'cannot be bundled from the audited root'
    );
  }
  await module.buildGatewayBundle({ root, outputRoot: scratch });
  return path.join(scratch, 'build', 'gateway');
}

async function emitReference(subtree, { root, scratch }) {
  if (subtree.id === 'build/src') return emitTypeScript({ root, scratch });
  if (subtree.id === 'build/renderer') return emitVite({ root, scratch });
  if (subtree.id === 'build/gateway') return emitGateway({ root, scratch });
  throw new Error(`no reference emitter for ${subtree.id}`);
}

// ── Tree manifests ──────────────────────────────────────────────────────────

function collectFiles(baseDir, relative = '', accumulator = []) {
  for (const entry of fs.readdirSync(path.join(baseDir, relative), { withFileTypes: true })) {
    const next = relative ? `${relative}/${entry.name}` : entry.name;
    if (entry.isDirectory()) collectFiles(baseDir, next, accumulator);
    else if (entry.isFile()) accumulator.push(next);
  }
  return accumulator;
}

function manifestFromEntries(entries) {
  const aggregate = crypto.createHash('sha256');
  let bytes = 0;
  const sorted = [...entries.keys()].sort();
  for (const relative of sorted) {
    const entry = entries.get(relative);
    bytes += entry.size;
    aggregate.update(`${relative}\0${entry.size}\0${entry.sha256}\n`);
  }
  return { entries, bytes, fileCount: entries.size, treeHash: aggregate.digest('hex') };
}

/**
 * `rel -> { size, sha256 }` plus a single aggregate hash over the sorted manifest.
 * Paths use forward slashes so a report reads the same on every platform.
 */
export function treeManifest(directory) {
  if (!fs.existsSync(directory) || !fs.statSync(directory).isDirectory()) return null;
  const entries = new Map();
  for (const relative of collectFiles(directory)) {
    const contents = fs.readFileSync(path.join(directory, relative));
    entries.set(relative, {
      size: contents.length,
      sha256: crypto.createHash('sha256').update(contents).digest('hex')
    });
  }
  return manifestFromEntries(entries);
}

/** A one-file manifest, so the single-file checks reuse the same diff and report. */
export function singleFileManifest(name, contents) {
  return manifestFromEntries(new Map([[
    name,
    { size: contents.length, sha256: crypto.createHash('sha256').update(contents).digest('hex') }
  ]]));
}

function diffManifests(fresh, disk) {
  if (!fresh) return [{ kind: 'no-reference' }];
  if (!disk) return [{ kind: 'missing-subtree' }];
  const issues = [];
  for (const [relative, freshEntry] of fresh.entries) {
    const diskEntry = disk.entries.get(relative);
    if (!diskEntry) issues.push({ kind: 'missing', relative, fresh: freshEntry });
    else if (diskEntry.sha256 !== freshEntry.sha256) {
      issues.push({ kind: 'differs', relative, fresh: freshEntry, disk: diskEntry });
    }
  }
  for (const [relative, diskEntry] of disk.entries) {
    if (!fresh.entries.has(relative)) issues.push({ kind: 'extra', relative, disk: diskEntry });
  }
  // A subtree with the same files in a different arrangement is still stale, but
  // the per-file issues above already describe it; this only catches the case
  // where nothing above fired yet the aggregate disagrees.
  if (issues.length === 0 && fresh.treeHash !== disk.treeHash) {
    issues.push({ kind: 'tree-hash' });
  }
  return issues;
}

// ── build/release-notes.md (generated, ships, was in no gate) ────────────────

/**
 * Compare the on-disk notes against what scripts/release-notes.mjs would write now.
 *
 * The file is GENERATED (CHANGELOG.md + package.json#version) and it SHIPS twice:
 * electron-builder bakes it into latest.yml `releaseNotes` (the in-app update offer)
 * and release.yml uses it as the GitHub release body. Nothing compared it to its
 * source, so a version bump without regenerating it published the previous
 * release's notes — or an empty string — under the new version.
 *
 * ABSENCE is reported, not failed, unless `require` is set: the file is gitignored
 * (.gitignore:46) and only `npm run build:release` -> prebuild:release writes it, so
 * a clean clone has none and `npm run build` must still succeed there. The release
 * gate passes `require` (CI generates it in the same step first), which makes a
 * missing file a failure exactly where it must exist.
 */
export async function verifyReleaseNotes({ root, artifactRoot = root, require: required = false }) {
  const notesModule = await loadReleaseNotesModule();
  const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  const changelogPath = path.join(root, notesModule.CHANGELOG_FILE);
  if (!fs.existsSync(changelogPath)) {
    throw new Error(`release notes: ${notesModule.CHANGELOG_FILE} not found at ${changelogPath}`);
  }
  const body = notesModule.extractReleaseNotes(fs.readFileSync(changelogPath, 'utf8'), packageJson.version);
  const expected = `${body}\n`;
  const onDiskPath = path.join(artifactRoot, ...notesModule.RELEASE_NOTES_FILE.split(path.sep));
  const fresh = singleFileManifest('release-notes.md', Buffer.from(expected, 'utf8'));

  if (!fs.existsSync(onDiskPath)) {
    return {
      subtree: RELEASE_NOTES_ID,
      producer: 'scripts/release-notes.mjs (CHANGELOG.md -> build/release-notes.md)',
      fresh,
      disk: null,
      required,
      unchecked: !required,
      issues: required
        ? [{ kind: 'missing-subtree', target: 'file' }]
        : [],
      ok: !required
    };
  }
  const disk = singleFileManifest('release-notes.md', fs.readFileSync(onDiskPath));
  const issues = diffManifests(fresh, disk);
  return {
    subtree: RELEASE_NOTES_ID,
    producer: 'scripts/release-notes.mjs (CHANGELOG.md -> build/release-notes.md)',
    fresh,
    disk,
    required,
    unchecked: false,
    issues,
    ok: issues.length === 0
  };
}

/**
 * scripts/release-notes.mjs is imported, never re-implemented: the gate must compare
 * against the SAME extractor that writes the file, or the two can disagree about
 * what the notes should be.
 */
async function loadReleaseNotesModule() {
  releaseNotesModule ??= await import(pathToFileURL(path.join(SCRIPT_DIR, 'release-notes.mjs')).href);
  return releaseNotesModule;
}

let releaseNotesModule = null;

// ── Packaged asar vs build/ (what actually ships) ───────────────────────────

/** Normalize an asar entry (`\build\gateway\server.mjs`) to `build/gateway/server.mjs`. */
function normalizeAsarEntry(entry) {
  return entry.split('\\').join('/').replace(/^\/+/, '');
}

/**
 * Read one entry out of the archive. Returns null when the archive simply does not
 * contain it; any other failure (corrupt header, truncated file) propagates as a
 * toolchain error so a broken archive is never reported as a stale file.
 */
function readAsarEntry(asar, archivePath, relative) {
  for (const candidate of [path.normalize(relative), relative]) {
    try {
      return asar.extractFile(archivePath, candidate);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (!/was not found in this archive/.test(message)) throw error;
    }
  }
  return null;
}

/**
 * Compare the packaged archive against build/ — the last gap in this gate.
 *
 * THE DEFECT: every check above compares build/ to the sources, but what a user
 * runs is app.asar. Measured on this tree: app.asar was written at 03:28 while the
 * sources were 03:51, and nothing noticed. A packaging step that silently reused a
 * previous archive (or a `files:` glob that stopped matching) would ship a stale
 * engine with a fully green build-freshness gate.
 *
 * WHAT IS COMPARED
 *   * required, from build/: build/gateway/server.mjs, build/renderer/index.html,
 *     every build/src/main/**\/*.js and every build/renderer/assets/* file;
 *   * every asar entry under build/gateway/, build/src/main/, build/renderer/ must
 *     exist in build/ with identical bytes — an entry the current build does not
 *     produce is a stale leftover (the old content-hashed renderer bundle is the
 *     realistic shape), and electron-builder copies the whole archive.
 * Entries the current build DOES produce but electron-builder filters out (the
 * `!build/src/test-support/**` and `!**\/*.map` rules, and the .d.ts files it drops)
 * are deliberately not required: the config decides what ships, this gate decides
 * whether what shipped is current.
 */
export function verifyPackagedAsar({ root, asarPath }) {
  const archivePath = asarPath ?? path.join(root, DEFAULT_ASAR_PATH);
  if (!fs.existsSync(archivePath)) {
    throw new Error(
      `packaged archive not found at ${archivePath}: run \`npm run package:dir\` first `
      + '(nothing was packaged, so there is nothing to compare)'
    );
  }
  const asar = resolveAsar(root);

  const allEntries = asar.listPackage(archivePath).map(normalizeAsarEntry);
  const directories = new Set();
  for (const entry of allEntries) {
    for (let index = entry.lastIndexOf('/'); index > 0; index = entry.lastIndexOf('/', index - 1)) {
      directories.add(entry.slice(0, index));
    }
  }
  const archiveFiles = allEntries.filter((entry) => !directories.has(entry));

  const expected = [];
  for (const relative of ASAR_REQUIRED_FILES) expected.push(relative);
  for (const directory of ASAR_REQUIRED_DIRECTORIES) {
    const absolute = path.join(root, ...directory.split('/'));
    if (!fs.existsSync(absolute)) {
      throw new Error(
        `${directory} does not exist under ${root}, so the archive cannot be compared against it: `
        + 'run `npm run build` first'
      );
    }
    for (const relative of collectFiles(absolute)) {
      if (directory === 'build/src/main' && !relative.endsWith('.js')) continue;
      expected.push(`${directory}/${relative}`);
    }
  }

  const issues = [];
  const freshEntries = new Map();
  for (const relative of [...new Set(expected)].sort()) {
    const onDisk = fs.readFileSync(path.join(root, ...relative.split('/')));
    const entry = {
      size: onDisk.length,
      sha256: crypto.createHash('sha256').update(onDisk).digest('hex')
    };
    freshEntries.set(relative, entry);
    const packaged = readAsarEntry(asar, archivePath, relative);
    if (packaged === null) {
      issues.push({ kind: 'missing', relative, fresh: entry });
      continue;
    }
    const packagedEntry = {
      size: packaged.length,
      sha256: crypto.createHash('sha256').update(packaged).digest('hex')
    };
    if (packagedEntry.sha256 !== entry.sha256) {
      issues.push({ kind: 'differs', relative, fresh: entry, disk: packagedEntry });
    }
  }

  const required = new Set(freshEntries.keys());
  for (const relative of archiveFiles) {
    if (!ASAR_COMPARED_PREFIXES.some((prefix) => relative.startsWith(prefix))) continue;
    if (!shipsFromBuild(relative)) continue;
    if (required.has(relative)) continue;
    const packaged = readAsarEntry(asar, archivePath, relative);
    if (packaged === null) continue;
    issues.push({
      kind: 'extra',
      relative,
      disk: { size: packaged.length, sha256: crypto.createHash('sha256').update(packaged).digest('hex') }
    });
  }

  const fresh = manifestFromEntries(freshEntries);
  return {
    ok: issues.length === 0,
    archivePath,
    fresh,
    archiveFileCount: archiveFiles.length,
    issues
  };
}

// ── Reporting ───────────────────────────────────────────────────────────────

const MAX_ISSUES_PER_SUBTREE = 8;

function shortHash(value) {
  return `${value.slice(0, 12)}…`;
}

function describeIssue(issue) {
  switch (issue.kind) {
    case 'missing-subtree':
      // The notes check reuses this kind, so the wording follows what is actually
      // absent: a required FILE that the generator did not write is not a directory.
      return issue.target === 'file'
        ? 'the file does not exist (the generator above writes it; --require-release-notes makes its absence a failure)'
        : 'the directory does not exist (a clean build would create it)';
    case 'no-reference':
      return 'the reference emit produced nothing';
    case 'tree-hash':
      return 'the file set matches but the aggregate hash differs';
    case 'missing':
      return `missing on disk    ${issue.relative} (a clean build writes ${issue.fresh.size} B sha256=${shortHash(issue.fresh.sha256)})`;
    case 'extra':
      return `extra on disk      ${issue.relative} (${issue.disk.size} B sha256=${shortHash(issue.disk.sha256)}; no clean build produces this file)`;
    case 'differs':
      return `differs            ${issue.relative} disk=${issue.disk.size} B sha256=${shortHash(issue.disk.sha256)} fresh=${issue.fresh.size} B sha256=${shortHash(issue.fresh.sha256)}`;
    default:
      return `${issue.kind} ${issue.relative ?? ''}`.trim();
  }
}

export function formatReport(results) {
  const lines = [];
  for (const result of results) {
    if (result.ok) {
      lines.push(
        `BUILD_FRESHNESS_VERIFIED ${result.subtree} files=${result.fresh.fileCount} `
        + `bytes=${result.fresh.bytes} tree=${result.fresh.treeHash}`
      );
      continue;
    }
    lines.push(`STALE_BUILD_ARTIFACT ${result.subtree}: ${result.issues.length} difference(s) vs a clean emit`);
    for (const issue of result.issues.slice(0, MAX_ISSUES_PER_SUBTREE)) {
      lines.push(`  ${describeIssue(issue)}`);
    }
    if (result.issues.length > MAX_ISSUES_PER_SUBTREE) {
      lines.push(`  … ${result.issues.length - MAX_ISSUES_PER_SUBTREE} more`);
    }
  }
  const stale = results.filter((result) => !result.ok).map((result) => result.subtree);
  if (stale.length === 0) {
    lines.push(`BUILD_FRESHNESS_OK ${results.length}/${results.length} shipped subtrees are byte-identical to a clean emit`);
  } else {
    lines.push(`BUILD_FRESHNESS_FAILED ${stale.length}/${results.length} stale: ${stale.join(', ')}`);
    lines.push('  fix: run `npm run build` — prebuild cleans build/ and every *.tsbuildinfo, then regenerates all of it');
  }
  return lines.join('\n');
}

/** One verdict line for the generated notes file, so its state is never implicit. */
export function formatReleaseNotesReport(result) {
  if (result.unchecked) {
    return `BUILD_FRESHNESS_UNCHECKED ${result.subtree}: not generated on this tree `
      + '(gitignored; `npm run build:release` writes it) — pass --require-release-notes to fail on absence';
  }
  if (result.ok) {
    return `BUILD_FRESHNESS_VERIFIED ${result.subtree} files=1 bytes=${result.fresh.bytes} `
      + `sha256=${result.fresh.treeHash.slice(0, 64)}`;
  }
  const lines = [`STALE_BUILD_ARTIFACT ${result.subtree}: 1 difference vs CHANGELOG.md`];
  for (const issue of result.issues.slice(0, MAX_ISSUES_PER_SUBTREE)) {
    lines.push(`  ${describeIssue(issue)}`);
  }
  lines.push('  fix: node scripts/release-notes.mjs (it regenerates build/release-notes.md from CHANGELOG.md)');
  return lines.join('\n');
}

export function formatAsarReport(result) {
  if (result.ok) {
    return `ASAR_FRESHNESS_VERIFIED ${result.archivePath} compared=${result.fresh.fileCount} `
      + `bytes=${result.fresh.bytes} tree=${result.fresh.treeHash} entries=${result.archiveFileCount}`;
  }
  const lines = [
    `STALE_PACKAGED_ASAR ${result.archivePath}: ${result.issues.length} difference(s) vs build/`,
    '  the packaged archive is what the user runs; rebuild it with `npm run package:dir`'
  ];
  for (const issue of result.issues.slice(0, MAX_ISSUES_PER_SUBTREE)) {
    lines.push(`  ${describeIssue(issue)}`);
  }
  if (result.issues.length > MAX_ISSUES_PER_SUBTREE) {
    lines.push(`  … ${result.issues.length - MAX_ISSUES_PER_SUBTREE} more`);
  }
  return lines.join('\n');
}

// ── Entry point ─────────────────────────────────────────────────────────────

/**
 * Verify every requested subtree. Throws only when a REFERENCE emit cannot be
 * produced (exit 2 at the CLI); a stale artifact is a normal `ok: false` result so
 * callers can report all subtrees in one pass instead of stopping at the first.
 */
export async function verifyBuildFreshness({
  root = DEFAULT_ROOT,
  artifactRoot = root,
  workDir,
  subtrees = SUBTREE_IDS
} = {}) {
  const requested = Array.isArray(subtrees) ? subtrees : [subtrees];
  const unknown = requested.filter((id) => !SUBTREE_IDS.includes(id));
  if (unknown.length > 0) {
    throw new Error(`unknown subtree(s) ${unknown.join(', ')}; known: ${SUBTREE_IDS.join(', ')}`);
  }
  const selected = SHIPPED_SUBTREES.filter((subtree) => requested.includes(subtree.id));

  const base = workDir ?? os.tmpdir();
  fs.mkdirSync(base, { recursive: true });
  // mkdtemp, never a fixed name: two verifiers (the postbuild hook and a test) can
  // run concurrently and must not delete each other's reference emit.
  const scratch = fs.mkdtempSync(path.join(base, 'nvgw-freshness-'));
  const results = [];
  try {
    for (const subtree of selected) {
      const referenceDir = await emitReference(subtree, { root, scratch: path.join(scratch, subtree.id.replace(/\//g, '-')) });
      const onDiskDir = path.join(artifactRoot, ...subtree.id.split('/'));
      const fresh = treeManifest(referenceDir);
      const disk = treeManifest(onDiskDir);
      const issues = diffManifests(fresh, disk);
      results.push({ subtree: subtree.id, producer: subtree.producer, fresh, disk, issues, ok: issues.length === 0 });
    }
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
  return { ok: results.every((result) => result.ok), results };
}

function parseArguments(argv) {
  const options = {
    subtrees: [],
    root: DEFAULT_ROOT,
    artifactRoot: null,
    workDir: null,
    asar: false,
    asarPath: null,
    requireReleaseNotes: false
  };
  for (let index = 0; index < argv.length; index += 1) {
    const flag = argv[index];
    const value = argv[index + 1];
    if (flag === '--subtree' && value) { options.subtrees.push(value); index += 1; }
    else if (flag === '--root' && value) { options.root = path.resolve(value); index += 1; }
    else if (flag === '--artifact-root' && value) { options.artifactRoot = path.resolve(value); index += 1; }
    else if (flag === '--work-dir' && value) { options.workDir = path.resolve(value); index += 1; }
    else if (flag === '--asar') { options.asar = true; }
    else if (flag === '--asar-path' && value) { options.asarPath = path.resolve(value); index += 1; }
    else if (flag === '--require-release-notes') { options.requireReleaseNotes = true; }
    else if (flag === '--help' || flag === '-h') { options.help = true; }
    else throw new Error(`unknown argument ${flag}`);
  }
  return options;
}

const invokedDirectly = process.argv[1]
  && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url;

if (invokedDirectly) {
  try {
    const options = parseArguments(process.argv.slice(2));
    if (options.help) {
      console.log('node scripts/verify-build-freshness.mjs [--subtree <id>]... [--root <dir>] [--artifact-root <dir>] [--work-dir <dir>]');
      console.log('       [--asar [--asar-path <app.asar>]] [--require-release-notes]');
      console.log(`subtrees: ${SUBTREE_IDS.join(', ')}; plus ${RELEASE_NOTES_ID}`);
      process.exitCode = 0;
    } else if (options.asar) {
      // Packaging mode: compares what SHIPS against build/. It needs no reference
      // emit, so it is cheap and is wired into CI right after package:dir.
      const result = verifyPackagedAsar({ root: options.root, asarPath: options.asarPath ?? undefined });
      console.log(formatAsarReport(result));
      process.exitCode = result.ok ? 0 : 1;
    } else {
      const { ok, results } = await verifyBuildFreshness({
        root: options.root,
        artifactRoot: options.artifactRoot ?? options.root,
        workDir: options.workDir ?? undefined,
        subtrees: options.subtrees.length > 0 ? options.subtrees : SUBTREE_IDS
      });
      const notes = await verifyReleaseNotes({
        root: options.root,
        artifactRoot: options.artifactRoot ?? options.root,
        require: options.requireReleaseNotes
      });
      console.log(formatReport(results));
      console.log(formatReleaseNotesReport(notes));
      process.exitCode = ok && notes.ok ? 0 : 1;
    }
  } catch (error) {
    console.error(`BUILD_FRESHNESS_UNVERIFIABLE: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 2;
  }
}
